create table if not exists contacts (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  name text not null,\n  email text,\n  phone text,\n  met_where text,\n  met_when date,\n  family text,\n  occupation text,\n  recreation text,\n  money text,\n  hobbies text,\n  dreams text,\n  needs_summary text,\n  needs_source text,\n  needs_confidence numeric,\n  needs_review_status text default 'unreviewed',\n  warmth text,\n  tags text[] default '{}',\n  created_at timestamptz not null default now()\n);\n\nalter table contacts enable row level security;\n\ndrop policy if exists \"contacts_v1_read\" on contacts;\ncreate policy \"contacts_v1_read\" on contacts for select using (true);\ndrop policy if exists \"contacts_v1_write\" on contacts;\ncreate policy \"contacts_v1_write\" on contacts for all using (true) with check (true);\n\ninsert into contacts (id, name, email, phone, met_where, met_when, family, occupation, recreation, money, hobbies, dreams, needs_summary, needs_source, needs_confidence, needs_review_status, warmth, tags) values\n('a1b2c3d4-0001-4000-8000-000000000001', 'Sarah Chen', 'sarah.chen@email.com', '555-0101', 'Tech conference', '2024-09-15', 'Married, 1 daughter', 'Software engineer at a fintech startup', 'Rock climbing, cooking', 'Looking to invest in real estate', 'Photography, reading', 'Financial independence by 45', 'Interested in real estate investing; values family time and work-life balance.', 'FORMHD-rule-based', 0.9, 'unreviewed', 'hot', '{\"investor\",\"hot-lead\"}'),\n('a1b2c3d4-0001-4000-8000-000000000002', 'Marcus Johnson', 'm.johnson@email.com', '555-0102', 'Gym', '2024-08-03', 'Single, no kids', 'Personal trainer', 'CrossFit, marathon running', 'Saving to open a fitness studio', 'Nutrition, meal prep', 'Own a gym within 2 years', 'Looking to start a fitness business; values health and entrepreneurship.', 'FORMHD-rule-based', 0.9, 'unreviewed', 'hot', '{\"entrepreneur\",\"hot-lead\"}'),\n('a1b2c3d4-0001-4000-8000-0000000